"use strict";
function bank(subject,prefix,outcome,rows){
 return rows.map((r,i)=>{
  const choices=[r[3],r[4],r[5],r[6]], shift=(i*3+prefix.length)%4;
  const options=choices.map((_,j)=>choices[(j-shift+4)%4]);
  return {id:prefix+"-"+String(i+1).padStart(2,"0"),grade:"Grade 10",subject,
   strand:r[0],substrand:r[1],learningOutcome:outcome,question:r[2],options,
   correctIndex:options.indexOf(r[3]),explanation:r[7],published:true};
 });
}
